def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # The two colored border segments are the paired endpoints of the pattern.
    runs = []
    for c in (0, w - 1):
        rows = [r for r in range(h) if grid[r][c] != bg]
        if rows:
            start = prev = rows[0]
            for r in rows[1:]:
                if r != prev + 1:
                    runs.append((c, start, prev + 1))
                    start = r
                prev = r
            runs.append((c, start, prev + 1))
    if len(runs) < 2:
        return out

    # Interior singleton-color marks point from their border toward the mark;
    # also echo each mark across the corresponding row of the opposite run.
    for c, start, end in runs:
        edge_color = grid[start][c]
        other_runs = [x for x in runs if x[0] != c and x[2] - x[1] == end - start]
        if not other_runs:
            continue
        other = min(other_runs, key=lambda x: abs(x[1] - start))
        for r in range(start, end):
            markers = [(x, grid[r][x]) for x in range(1, w - 1)
                       if grid[r][x] != bg and grid[r][x] != edge_color]
            if not markers:
                continue
            # Typically one mark per row; process each independently.
            for x, color in markers:
                if c == 0:
                    for k in range(c + 1, x):
                        out[r][k] = color
                else:
                    for k in range(x + 1, c):
                        out[r][k] = color
                out[r][x] = 4
                pr = other[1] + (r - start)
                if other[1] <= pr < other[2]:
                    for k in range(1, w - 1):
                        out[pr][k] = color
    return out
